import boto3
from botocore.exceptions import ClientError

def upload_to_s3(bucket_name: str, object_key: str, payload):
    """
    Uploads a file or byte stream to Amazon S3.
    payload can be a file-like object with a read() method or a bytes/bytearray sequence.
    """
    s3_client = boto3.client('s3')

    if hasattr(payload, 'read'):
        try:
            s3_client.upload_fileobj(payload, bucket_name, object_key)
        except ClientError as e:
            raise RuntimeError(f"Failed to upload stream to S3 bucket '{bucket_name}': {e}") from e
    elif isinstance(payload, (bytes, bytearray)):
        try:
            s3_client.put_object(Bucket=bucket_name, Key=object_key, Body=payload)
        except ClientError as e:
            raise RuntimeError(f"Failed to upload bytes to S3 bucket '{bucket_name}': {e}") from e
    else:
        raise TypeError("payload must be a file-like object or bytes/bytearray")
